mapper.select:
select * from new_employee_personal_information_card
ni left join new_reg ur
on ni.reg_id=ur.id
LEFT JOIN `yh_user_make_card` AS c ON ur.`user_code` = c.`User_Code`
LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id


    and c.Org_Id = #{orgCode}


    and ni.sex = #{sex}



    and ur.department LIKE CONCAT('%', #{department}, '%')


    and ur.v888 LIKE CONCAT('%', #{team}, '%')


    and ni.name LIKE CONCAT('%', #{name}, '%')



    and ni.time >  #{startTime}


    and ni.time <  #{endTime}



LIMIT #{begin}, #{limit};

select count(*) from new_employee_personal_information_card
ni left join new_reg ur
on ni.reg_id=ur.id
LEFT JOIN `yh_user_make_card` AS c ON ur.`user_code` = c.`User_Code`
LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id


    and c.Org_Id = #{orgCode}


    and ni.sex = #{sex}



    and ur.department LIKE CONCAT('%', #{department}, '%')


    and ur.v888 LIKE CONCAT('%', #{team}, '%')


    and ni.name LIKE CONCAT('%', #{name}, '%')



    and ni.time >  #{startTime}


    and ni.time <  #{endTime}
